package es.sgcorredores.mobile;
import android.app.*;import android.os.*;import android.webkit.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.Manifest;
public class MainActivity extends Activity {
 WebView web; ValueCallback<Uri[]> files; PermissionRequest pending;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff092c20);web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);CookieManager.getInstance().setAcceptCookie(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(true);web.getSettings().setCacheMode(WebSettings.LOAD_DEFAULT);getWindow().setNavigationBarColor(0xff092c20);web.getSettings().setMediaPlaybackRequiresUserGesture(false);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if("https".equals(u.getScheme())&&"sg-corredores.github.io".equals(u.getHost()))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){}return true;}});
 web.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=cb;try{startActivityForResult(p.createIntent(),12);return true;}catch(Exception e){files=null;return false;}}public void onPermissionRequest(PermissionRequest r){runOnUiThread(()->{if(!"https://sg-corredores.github.io".equals(r.getOrigin().toString())){r.deny();return;}pending=r;java.util.ArrayList<String> perms=new java.util.ArrayList<>();for(String x:r.getResources()){if(x.equals(PermissionRequest.RESOURCE_AUDIO_CAPTURE))perms.add(Manifest.permission.RECORD_AUDIO);else if(x.equals(PermissionRequest.RESOURCE_VIDEO_CAPTURE))perms.add(Manifest.permission.CAMERA);else{r.deny();pending=null;return;}}if(perms.stream().allMatch(p->checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED)){r.grant(r.getResources());pending=null;}else requestPermissions(perms.toArray(new String[0]),13);});}});
 web.loadUrl("https://sg-corredores.github.io/sg-corredores-app/Index.html");}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==13&&pending!=null){boolean ok=g.length>0;for(int x:g)ok&=x==PackageManager.PERMISSION_GRANTED;if(ok)pending.grant(pending.getResources());else pending.deny();pending=null;}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==12&&files!=null){files.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(c,d));files=null;}}
 protected void onPause(){CookieManager.getInstance().flush();super.onPause();}
 public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}